"""Build a small self-contained visual verdict from inspected native evidence."""
from pathlib import Path
import json,html
HERE=Path(__file__).resolve().parent
score=json.loads((HERE/'SCORECARD.json').read_text());counts=score['counts']
def picture(name):return 'screenshots/'+name
body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RC MetaStudio 0.5.0 audit verdict</title><style>
*{box-sizing:border-box}body{margin:0;padding:0;font:16px/1.5 var(--font-sans,system-ui),sans-serif;background:transparent;color:var(--foreground,#202b3a)}main{max-width:1040px;margin:auto}h1{font-size:28px;line-height:1.2;margin:4px 0 12px}h2{font-size:20px;margin:0 0 8px}.status{background:var(--warning-surface,#fff2e7);border-left:5px solid #a64d09;padding:16px;margin:16px 0;border-radius:4px}.muted{color:var(--muted-foreground,#536173)}.counts{display:flex;gap:12px;flex-wrap:wrap}.count{padding:12px 16px;background:var(--card,#fff);border:1px solid var(--border,#d7dde5);border-radius:8px;flex:1;min-width:140px}.count b{font-size:26px;display:block}.cards{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.card{background:var(--card,#fff);border:1px solid var(--border,#d7dde5);border-radius:8px;padding:16px}.card p{margin:8px 0}.card img{width:100%;height:auto;display:block;border:1px solid var(--border,#d7dde5);cursor:zoom-in}button{background:#214b72;color:white;border:0;padding:9px 14px;border-radius:5px;cursor:pointer}dialog{max-width:96vw;max-height:96vh;padding:12px;border:1px solid #8794a4;border-radius:8px}dialog img{max-width:90vw;max-height:83vh;object-fit:contain;display:block}dialog::backdrop{background:#000b}@media(max-width:700px){body{padding:0}.cards{grid-template-columns:1fr}}
</style><main><p class="muted">Independent native re-audit · Linux/X11 · pinned R 4.6.1</p><h1>RC MetaStudio v0.5.0</h1><div class="status"><strong>Hold the merge for two heading defects.</strong><br>Statistical cross-checks pass; publication identity and layout still need repair.</div><div class="counts">'''
for key in ('fixed','improved','unchanged','regressed'):body+=f'<div class="count"><b>{counts.get(key,0)}</b>{key} prior IDs</div>'
body+='</div><p class="muted">100 historical IDs · 8 new findings: 2 medium, 6 low · 91 authority comparisons pass · 415 original numerical fields exact.</p><div class="cards">'
for title,text,name in [
('R6-03 · RevMan heading collision','The longest supported arm heading crosses the device top and overlaps the caption, including actual SVG output.','project-round6-polish-180-0-measured-wrapped-arm-headers.png'),
('R6-06 · Automatic heading truncation','The wizard accepts 89 characters; generated headings retain only 80. A generic tooltip discloses the cap, but there is no inline notice that the accepted name was shortened.','R6-06-171-0-round5-arm-wizard.png')]:
 body+=f'<article class="card"><h2>{html.escape(title)}</h2><p>{html.escape(text)}</p><img alt="Native evidence for {html.escape(title)}; click to enlarge" tabindex="0" src="{picture(name)}"></article>'
body+='''</div><p>The report and contact sheet retain exact reproductions, every prior-ID status, inspected screenshots and command/log pointers. Application scaling, native driving and export decoding are distinguished from package, OS-DPI and screen-reader qualification.</p><dialog><button autofocus>Close</button><img alt="Enlarged native audit evidence"></dialog></main><script>const d=document.querySelector('dialog'),large=d.querySelector('img');for(const im of document.querySelectorAll('.card img')){const show=()=>{large.src=im.src;large.alt=im.alt;d.showModal()};im.onclick=show;im.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}}d.querySelector('button').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()};</script></html>'''
(HERE/'verdict.html').write_text(body)
print('verdict bytes',len(body))
